plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.android)
    alias(libs.plugins.maven.publish)
    alias(libs.plugins.rust.gradle)
}

// JitPack builds release tags with VERSION set to the tag; local builds use the development version.
val libraryVersion = System.getenv("VERSION")?.removePrefix("v") ?: "0.1.0-SNAPSHOT"

// Kotlin bindings generated by uniffi from the native library.
val uniffiDir = layout.buildDirectory.dir("generated/uniffi")

// The native library built by the rust plugin, linked by the benchmark's JNI glue.
val rustJniLibsDir = layout.buildDirectory.dir("rustJniLibs/android")

android {
    namespace = "com.acurast.processor"
    compileSdk = 35
    ndkVersion = "29.0.14206865"

    defaultConfig {
        minSdk = 26
        version = libraryVersion
        ndk {
            abiFilters.addAll(setOf("armeabi-v7a", "arm64-v8a"))
        }
        externalNativeBuild {
            cmake {
                targets("acubench")
                arguments("-DRUST_JNI_LIBS=${rustJniLibsDir.get().asFile.absolutePath}")
            }
        }
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
        debug {
            externalNativeBuild {
                cmake {
                    targets("acubench", "acubenchtest")
                }
            }
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
    }
    kotlinOptions {
        jvmTarget = "11"
    }
    externalNativeBuild {
        cmake {
            path = file("src/main/cpp/CMakeLists.txt")
            version = "3.22.1"
        }
    }
    sourceSets["main"].java.srcDir(uniffiDir)
}

cargo {
    module = "../../processor-ffi"
    libname = "acurast_processor_ffi"
    targets = listOf("arm", "arm64")
    profile = "release"
    prebuiltToolchains = true
    // The linker wrapper is a Python script; macOS only has `python3`.
    pythonCommand = "python3"
    apiLevel = 29
    // The Cargo workspace's target/ is at the repo root.
    targetDirectory = "../../target"
}

publishing {
    publications {
        register<MavenPublication>("maven") {
            groupId = "com.github.acurast"
            artifactId = "acurast-processor-libs"
            version = libraryVersion

            afterEvaluate {
                from(components["release"])
            }
        }
    }
}

dependencies {
    compileOnly(libs.jna)
    implementation(libs.androidx.core.ktx)
    implementation(libs.kotlinx.coroutines.core)
    testImplementation(libs.jna)
    testImplementation(libs.junit)
    testImplementation(libs.kotlin.test)
    testImplementation(libs.kotlinx.coroutines.test)
    androidTestImplementation(libs.androidx.junit)
    androidTestImplementation(libs.androidx.espresso.core)
}

val uniffiBindings = tasks.register<Exec>("uniffiBindings") {
    dependsOn("cargoBuild")
    workingDir("../..")
    commandLine(
        "cargo", "run", "--release",
        "-p", "uniffi-bindgen",
        "--", "generate",
        "--library", "target/aarch64-linux-android/release/libacurast_processor_ffi.so",
        "--language", "kotlin",
        "--no-format",
        "--out-dir", uniffiDir.get().asFile.absolutePath,
    )
}

tasks.configureEach {
    if (name == "mergeDebugJniLibFolders" || name == "mergeReleaseJniLibFolders") {
        dependsOn("cargoBuild")
        // The rust plugin's jniLibs dir is merged but not tracked, so a rebuilt .so would be skipped.
        inputs.dir(rustJniLibsDir).withPropertyName("rustJniLibs")
    }
    // The benchmark's JNI glue links the native library.
    if (name.startsWith("configureCMake") || name.startsWith("buildCMake")) {
        dependsOn("cargoBuild")
    }
}

tasks.matching { it.name.startsWith("compile") && it.name.endsWith("Kotlin") }.configureEach {
    dependsOn(uniffiBindings)
}
